data.default.conf:
server {
    listen 8080;

    location / {
        default_type text/html;
        return 200 '<html><body><h1>Kubernetes Security Lab</h1><h2>Cloud Security & DevSecOps</h2><p>Frontend: Operational</p><a href="/api/">Backend API</a><br><a href="/api/health">Health Check</a></body></html>';
    }

    location /api/ {
        proxy_pass http://backend.backend.svc.cluster.local:8000/;
    }
}
